/* The flipbook: a stepper over frames generated by running the real CLI.

   State lives in the URL hash (#capture, #refused, …) so a frame is linkable
   and the back button works. Keyboard: arrows step, Home/End jump. Nothing
   auto-plays — the unit of meaning is a command, which is discrete, and the
   reader owns the clock. */
(function () {
  "use strict";

  var book = window.__FLIP_BOOK__;
  var spec = window.__FLIP_SPEC__;
  var kit = window.flipsite;
  if (!book || !book.steps || !book.steps.length || !kit) return;

  var steps = book.steps;
  var index = 0;

  var el = {
    acts: document.getElementById("fb-acts"),
    act: document.getElementById("fb-act"),
    n: document.getElementById("fb-n"),
    total: document.getElementById("fb-total"),
    title: document.getElementById("fb-title"),
    say: document.getElementById("fb-say"),
    narrative: document.getElementById("fb-narrative"),
    commands: document.getElementById("fb-commands"),
    tree: document.getElementById("fb-tree"),
    legend: document.getElementById("fb-legend"),
    record: document.getElementById("fb-record"),
    prev: document.getElementById("fb-prev"),
    next: document.getElementById("fb-next"),
    spec: document.getElementById("fb-spec"),
    vintage: document.getElementById("fb-vintage")
  };

  // -- the stepper: dots grouped by act ------------------------------------
  var dots = [];
  (function buildStepper() {
    var currentAct = null;
    var group = null;
    steps.forEach(function (step, i) {
      if (step.act !== currentAct) {
        currentAct = step.act;
        group = document.createElement("div");
        group.className = "fb__act";
        var name = document.createElement("span");
        name.className = "fb__act-name";
        name.textContent = step.act;
        var row = document.createElement("div");
        row.className = "fb__dots";
        group.appendChild(name);
        group.appendChild(row);
        el.acts.appendChild(group);
        group = row;
      }
      var dot = document.createElement("button");
      dot.type = "button";
      dot.className = "fb__dot";
      dot.textContent = String(step.n);
      dot.title = step.act + " — " + step.title;
      dot.setAttribute("aria-label", "Step " + step.n + ": " + step.title);
      if (step.refused) dot.setAttribute("data-refused", "yes");
      dot.addEventListener("click", function () { go(i, true); });
      group.appendChild(dot);
      dots.push(dot);
    });
  })();

  // -- the file tree --------------------------------------------------------
  // Rendered as a real nested list from the flat path list, so screen readers
  // get the hierarchy and the indentation is not decorative whitespace.
  function renderTree(entries) {
    var root = { dirs: {}, files: [] };
    entries.forEach(function (entry) {
      var parts = entry.path.split("/");
      var node = root;
      for (var i = 0; i < parts.length - 1; i += 1) {
        node.dirs[parts[i]] = node.dirs[parts[i]] || { dirs: {}, files: [] };
        node = node.dirs[parts[i]];
      }
      node.files.push({ name: parts[parts.length - 1], state: entry.state });
    });

    function build(node) {
      var list = document.createElement("ul");
      Object.keys(node.dirs).sort().forEach(function (name) {
        var item = document.createElement("li");
        var label = document.createElement("span");
        label.className = "dir";
        label.textContent = "▸ " + name + "/";
        item.appendChild(label);
        item.appendChild(build(node.dirs[name]));
        list.appendChild(item);
      });
      node.files.sort(function (a, b) { return a.name.localeCompare(b.name); })
        .forEach(function (file) {
          var item = document.createElement("li");
          item.className = "file"
            + (file.state === "added" ? " is-added" : "")
            + (file.state === "changed" ? " is-changed" : "");
          var mark = document.createElement("span");
          mark.className = "mark";
          mark.textContent = file.state === "added" ? "+" : (file.state === "changed" ? "~" : "");
          mark.setAttribute("aria-hidden", "true");
          item.appendChild(mark);
          item.appendChild(document.createTextNode(file.name));
          if (file.state !== "same") {
            var sr = document.createElement("span");
            sr.className = "visually-hidden";
            sr.textContent = file.state === "added" ? " (added this step)" : " (changed this step)";
            item.appendChild(sr);
          }
          list.appendChild(item);
        });
      return list;
    }

    el.tree.textContent = "";
    el.tree.appendChild(build(root));
  }

  // -- render one frame -----------------------------------------------------
  function render() {
    var step = steps[index];

    el.act.textContent = step.act;
    el.n.textContent = String(step.n);
    el.total.textContent = String(steps.length);
    el.title.textContent = step.title;
    el.narrative.textContent = "";
    el.narrative.appendChild(kit.codeify(step.narrative));

    el.say.textContent = "";
    if (step.say) {
      var bubble = document.createElement("div");
      bubble.className = "bubble";
      var who = document.createElement("b");
      who.textContent = "You say";
      bubble.appendChild(who);
      bubble.appendChild(document.createTextNode(step.say));
      el.say.appendChild(bubble);
    } else {
      var quiet = document.createElement("p");
      quiet.className = "unprompted";
      quiet.textContent = "Nobody asked for this step — the notebook's discipline has the agent do it anyway.";
      el.say.appendChild(quiet);
    }

    el.commands.textContent = "";
    step.commands.forEach(function (command) {
      var line = document.createElement("div");
      line.className = "cmd";
      var code = document.createElement("code");
      code.textContent = command;
      line.appendChild(code);
      el.commands.appendChild(line);
    });
    if (step.refused) {
      var note = document.createElement("p");
      note.className = "record__caption";
      note.style.padding = "0";
      note.style.border = "0";
      note.textContent = "This command exits " + step.exit_code + ".";
      el.commands.appendChild(note);
    }

    renderTree(step.tree);
    var added = step.tree.filter(function (t) { return t.state === "added"; }).length;
    var changed = step.tree.filter(function (t) { return t.state === "changed"; }).length;
    el.legend.textContent = added || changed
      ? "· " + added + " added, " + changed + " changed"
      : "· unchanged";

    el.record.textContent = "";
    el.record.appendChild(kit.record({
      path: step.record.path,
      refused: step.refused,
      truncated: step.record.truncated,
      text: step.record.text,
      caption: step.record.caption
    }));

    el.spec.href = kit.specHref(step.spec, spec && spec.sections);
    el.spec.textContent = kit.specLabel(step.spec, spec && spec.sections);

    dots.forEach(function (dot, i) {
      if (i === index) dot.setAttribute("aria-current", "step");
      else dot.removeAttribute("aria-current");
      if (i <= index) dot.setAttribute("data-seen", "yes");
    });

    el.prev.disabled = index === 0;
    el.next.disabled = index === steps.length - 1;

    // The command lines are new DOM, so re-attach their copy buttons.
    if (kit.enhance) kit.enhance();
  }

  function go(next, push) {
    index = Math.max(0, Math.min(steps.length - 1, next));
    render();
    var id = steps[index].id;
    if (push && window.history && window.history.pushState) {
      window.history.pushState({ step: id }, "", "#" + id);
    } else if (push) {
      window.location.hash = id;
    }
  }

  function fromHash() {
    var id = (window.location.hash || "").replace(/^#/, "");
    for (var i = 0; i < steps.length; i += 1) {
      if (steps[i].id === id) return i;
    }
    return 0;
  }

  el.prev.addEventListener("click", function () { go(index - 1, true); });
  el.next.addEventListener("click", function () { go(index + 1, true); });
  window.addEventListener("popstate", function () { go(fromHash(), false); });
  window.addEventListener("hashchange", function () { go(fromHash(), false); });

  document.addEventListener("keydown", function (event) {
    if (event.metaKey || event.ctrlKey || event.altKey) return;
    var tag = (event.target.tagName || "").toLowerCase();
    if (tag === "input" || tag === "textarea" || event.target.isContentEditable) return;
    if (event.key === "ArrowRight") { go(index + 1, true); event.preventDefault(); }
    else if (event.key === "ArrowLeft") { go(index - 1, true); event.preventDefault(); }
    else if (event.key === "Home") { go(0, true); event.preventDefault(); }
    else if (event.key === "End") { go(steps.length - 1, true); event.preventDefault(); }
  });

  if (el.vintage && book.generated) {
    var stamp = document.createElement("span");
    stamp.textContent = " Generated " + book.generated.replace("T", " ").replace("+00:00", " UTC") + ".";
    el.vintage.appendChild(stamp);
  }

  go(fromHash(), false);
})();
